local LyreMaker = {}
local PRODUCTS = {
    simple_wooden_lyre = { name = "Preprosta lesena lira", woodCost = 2, ropeCost = 1, time = 3, cost = 40, happiness = 2, music = 18, description = "Preprosta lesena lira za potujoče pevce." },
    tortoise_shell_lyre = { name = "Slonovinasta lira", woodCost = 2, leatherCost = 1, ropeCost = 1, time = 6, cost = 130, happiness = 3, music = 35, prestige = 2, description = "Lira s slonovinastim okrasjem za trgovce." },
    bronze_strung_lyre = { name = "Bronastovrvena lira", woodCost = 2, bronzeCost = 2, leatherCost = 1, time = 9, cost = 320, happiness = 4, music = 50, prestige = 6, description = "Lira z bronastimi strunami za plemiče." },
    silver_string_lyre = { name = "Srebrnovrvena lira", woodCost = 3, silverCost = 2, bronzeCost = 1, leatherCost = 1, time = 13, cost = 760, happiness = 5, music = 65, prestige = 14, description = "Lira s srebrnimi strunami za visoke plemiče." },
    gold_trimmed_lyre = { name = "Zlatookrasna lira", woodCost = 3, goldCost = 2, silverCost = 1, bronzeCost = 1, leatherCost = 1, jewelCost = 1, time = 17, cost = 1700, happiness = 7, music = 80, prestige = 27, description = "Zlatookrasna lira z draguljem za visoko plemstvo." },
    royal_apollo_lyre = { name = "Kraljevska Apolonova lira", woodCost = 4, goldCost = 3, silverCost = 2, bronzeCost = 1, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 3900, happiness = 13, music = 95, prestige = 58, description = "Velika kraljevska Apolonova lira z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    lyre_workshop = { name = "Lirna delavnica", cost = { gold = 220, wood = 120, stone = 80, leather = 6 }, upkeep = 5, qualityBonus = 5 },
    stringed_loft = { name = "Strunska podstrešje", cost = { gold = 800, wood = 240, stone = 220, bronze = 6, leather = 8 }, upkeep = 18, qualityBonus = 18 },
    master_luthier_atelier = { name = "Mojstrski lutar atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_lyre_palace = { name = "Kraljevska lirna palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
LyreMaker.woodStock = 16; LyreMaker.leatherStock = 12; LyreMaker.ropeStock = 10; LyreMaker.bronzeStock = 8; LyreMaker.silverStock = 6; LyreMaker.goldStock = 6; LyreMaker.jewelStock = 4; LyreMaker.pearlStock = 4
LyreMaker.productStock = {}; LyreMaker.buildings = {}; LyreMaker.maker = nil; LyreMaker.activeMaking = {}; LyreMaker.totalProducts = 0; LyreMaker.dayTimer = 0
function LyreMaker.init() LyreMaker.woodStock=16; LyreMaker.leatherStock=12; LyreMaker.ropeStock=10; LyreMaker.bronzeStock=8; LyreMaker.silverStock=6; LyreMaker.goldStock=6; LyreMaker.jewelStock=4; LyreMaker.pearlStock=4; LyreMaker.productStock={}; LyreMaker.buildings={}; LyreMaker.maker=nil; LyreMaker.activeMaking={}; LyreMaker.totalProducts=0; LyreMaker.dayTimer=0; print("[LyreMaker] Royal Lyre Maker System initialized (6 products, 4 buildings)") end
function LyreMaker.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LyreMaker.maker={name=n or ("Lutar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lutar najet: %s (spretnost: %d)",LyreMaker.maker.name,s),"success") end; return true end
function LyreMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LyreMaker.build(id) local ok,e=LyreMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LyreMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LyreMaker.getQualityBonus() local b=0; for _,bd in ipairs(LyreMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LyreMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and LyreMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LyreMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.ropeCost and LyreMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.bronzeCost and LyreMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and LyreMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LyreMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LyreMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LyreMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LyreMaker.buildings==0 then return false,"Potrebna lirna delavnica" end; if not LyreMaker.maker then return false,"Potreben lutar" end; return true end
function LyreMaker.make(pt,qty) qty=qty or 1; local ok,e=LyreMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then LyreMaker.woodStock=LyreMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LyreMaker.leatherStock=LyreMaker.leatherStock-d.leatherCost*qty end; if d.ropeCost then LyreMaker.ropeStock=LyreMaker.ropeStock-d.ropeCost*qty end; if d.bronzeCost then LyreMaker.bronzeStock=LyreMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then LyreMaker.silverStock=LyreMaker.silverStock-d.silverCost*qty end; if d.goldCost then LyreMaker.goldStock=LyreMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LyreMaker.jewelStock=LyreMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LyreMaker.pearlStock=LyreMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LyreMaker.maker then t=math.max(1,t-math.floor(LyreMaker.maker.skill/13)) end; table.insert(LyreMaker.activeMaking,{id="lyre_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,music=d.music or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LyreMaker.completeMaking(m) local q=1.0+(LyreMaker.getQualityBonus()/100); if LyreMaker.maker then q=q+(LyreMaker.maker.skill/150) end; q=math.min(2.4,q); LyreMaker.productStock[m.productType]=(LyreMaker.productStock[m.productType] or 0)+m.quantity; LyreMaker.totalProducts=LyreMaker.totalProducts+m.quantity; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if LyreMaker.maker then LyreMaker.maker.itemsMade=LyreMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LyreMaker.maker.skill=math.min(100,LyreMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lira izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"lyre.completed",{productName=m.productName,music=m.music,prestige=m.prestige,happiness=m.happiness}) end end
function LyreMaker.update(dt) if not _G.state then return end; LyreMaker.dayTimer=LyreMaker.dayTimer+dt; if LyreMaker.dayTimer>=30 then LyreMaker.dayTimer=0; for i=#LyreMaker.activeMaking,1,-1 do local m=LyreMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LyreMaker.completeMaking(m); table.remove(LyreMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LyreMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LyreMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LyreMaker.getStats() return {woodStock=LyreMaker.woodStock,leatherStock=LyreMaker.leatherStock,ropeStock=LyreMaker.ropeStock,bronzeStock=LyreMaker.bronzeStock,silverStock=LyreMaker.silverStock,goldStock=LyreMaker.goldStock,jewelStock=LyreMaker.jewelStock,pearlStock=LyreMaker.pearlStock,productStock=LyreMaker.productStock,numBuildings=#LyreMaker.buildings,hasMaker=LyreMaker.maker~=nil,makerName=LyreMaker.maker and LyreMaker.maker.name or "—",makerSkill=LyreMaker.maker and LyreMaker.maker.skill or 0,activeMaking=#LyreMaker.activeMaking,totalProducts=LyreMaker.totalProducts} end
return LyreMaker
